SourceCode.Declaration:
/// <summary>
/// Contract class representing the response when an outbound message is fetched
/// </summary>
[DataContract]
public class OMGOutboundMessageContract
{
    OMGMessageGUID      messageGUID;
    OMGMessageName      messageName;
    str                 message;
    boolean             base64Encoded;
    DataAreaId          company;
    FilenameType        filenameType;
    boolean             more;

}

Method.Source:
[DataMember('FilenameType')]
public FilenameType parmFilenameType(FilenameType    _filenameType = filenameType)
{
    filenameType = _filenameType;
    return filenameType;
}

[DataMember('Base64Encoded')]
public boolean parmBase64Encoded(boolean    _base64Encoded = base64Encoded)
{
    base64Encoded = _base64Encoded;
    return base64Encoded;
}

[DataMember('MessageGUID')]
public OMGMessageGUID parmMessageGUID(OMGMessageGUID    _messageGUID = messageGUID)
{
    messageGUID = _messageGUID;
    return messageGUID;
}

[DataMember('Name')]
public OMGMessageName parmMessageName(OMGMessageName    _messageName = messageName)
{
    messageName = _messageName;
    return messageName;
}

[DataMember('Message')]
public str parmMessage(str    _message = message)
{
    message = _message;
    return message;
}

[DataMember('Company')]
public DataAreaId parmCompany(DataAreaId    _company = company)
{
    company = _company;
    return company;
}

[DataMember('More')]            
public boolean parmMore(boolean _more = more)
{
    more = _more;

    return more;
}
